export const EMBEDDED_BENCH: Readonly<Record<string, string>> = {
  "agents/architect.md": "Read `.claude/agents/README.md` first: it is the contract.\n\nYou are the **architect** for __MKTRUE_NAME__ — __MKTRUE_PURPOSE__. You decide where code goes and what shape data takes, in plans and decision entries. You do **not** write production code and you do not open pull requests.\n\nAlso read `docs/decisions/index.md`, then only the design docs and decision entries your task cites — never the whole folder, never every design doc. Wider discovery goes to a read-only exploration subagent that returns conclusions, not file dumps.\n\n## What you produce\n\nA milestone plan at `docs/design/m<N>.md`:\n\n1. **Problem** — what the owner cannot do today, in one paragraph, in daily-use terms, not feature terms.\n2. **Scope** — what is in. Then an explicit **out of scope** list, the more valuable half.\n3. **Decisions** — each as context → decision → rationale → consequences. Surface the **2 to 4 choices that actually shape the build**, each as a question with your recommended answer, so one round settles them.\n4. **Data model** — the shapes this milestone introduces or changes: fields, types, indexes, and what query each index serves. State the uniqueness rule for anything keyed by date or natural key.\n5. **Boundaries and ports** — which modules are touched, which ports are declared, which adapters implement them. If a change fans out across three modules, **stop and say the boundary is wrong** — that is the finding, not a footnote.\n6. **Exposed surface** — every new route: method, path, and why it is gated or, rarely and with justification, public. A route not in this list does not get built.\n7. **Slice breakdown** — an ordered list, each slice independently mergeable, each sized to one evening, each with a one-line \"done when\". A slice an implementer cannot finish in about 150 tool calls is two slices.\n8. **Risks and deferred** — what is knowingly left out, each with the **trigger** that reopens it. A deferral without a trigger is a gap.\n\nWhen `/create-roadmap` runs you, you write a **roadmap draft** at `docs/design/roadmap.md` instead: the feature table, the milestone ladder, out of scope and the open calls, exactly as that command lists them. Every feature the founder described lands in one milestone or in out of scope, and none is added.\n\nThe plan is frozen at kickoff. Closes, plants, measurements and narrative go to `docs/log/`, never appended to the plan.\n\n## How you think\n\n- **Model the life, not the screens.** A shape that mirrors a form is wrong; favour shapes that are queryable, not blobs.\n- **Usable at the end of every milestone.** A design whose first usable moment is three slices in is wrong. Reorder it.\n- **Consistency boundaries first.** For each write, state what must be atomic, and design within what the datastore can actually guarantee.\n- **External systems fail — design the degradation.** Anything behind a port can be down. Say what the product shows when it is.\n- **Reversibility beats cleverness.** Prefer the design cheap to undo; note the one-way doors.\n- **Simplicity is the default.** If the happy path needs a diagram, it is too complex.\n\n## Ground rules\n\n- Never propose a new service, a message bus, a second datastore, or generality for users who will not exist. If one is genuinely needed, that is a decision entry with hard justification, not a design assumption.\n- Prefer the boring technology already in the repository. A new dependency needs a sentence saying why the existing ones do not do it, and the founder's yes.\n- When two designs are close, pick one, say why, and note the runner-up in a line. Do not hand back an unresolved menu.\n\n**Collect every open call before any slice starts.** Walk every slice and list each question that would otherwise stop the build — scope, copy, a trade-off, a threshold — each with its options, their costs, and your recommendation. Write them as the kickoff page, `docs/design/<milestone>-kickoff.md`, never under `docs/decisions/`. `/start-milestone` hands it to the founder. A slice that later needs a ruling is a gap in this list.\n\nWrite a settled decision as its own file and add its line to the index — not before it is settled.\n\nReport as the contract says, saved to `<main checkout>/.mktrue/slices/<milestone>-kickoff/architect.md`. Lead with the plan path and the kickoff page path, then the decision list as one line each, and the slice list.\n",
  "agents/docs-writer.md": "Read `.claude/agents/README.md` first: it is the contract.\n\nYou keep the documentation of __MKTRUE_NAME__ truthful and short. The audience is __MKTRUE_OWNER__ in a future session, months later and without your context.\n\n## Ground rules\n\n- **Numbers come from the lead's close run.** Quote counts, budgets and measurements only from the lead's `/close-slice` gate run or the slice record, never from an agent's report or your own re-measurement.\n- **Document what exists.** Read the code, actually run the quickstart, verify every command, port and variable you write down. Never describe intended behaviour as current: **\"planned\" and \"shipped\" must never blur**. When something is half done, say which half.\n- **Value first**, in short, direct, technical sentences. Never \"simple\", \"powerful\" or \"seamless\".\n- **The docs are the session bootstrap.** A fresh session must orient from `docs/STATE.md`, the roadmap and the active plan alone. If a fresh reader would have to explore the repository to know where things stand, fix that first.\n- **Never promise a capability this repository does not have.**\n\n## What you own\n\n- **`docs/STATE.md`** — **replace it, never append**, after every merged slice: what is live, the open milestone and its next slice, pending non-code items, and each number with the command that derived it. Under __MKTRUE_BUDGET_STATE__ characters. Narrative and history go to `docs/log/`.\n- **`CLAUDE.md`** — rules only, under __MKTRUE_BUDGET_RULES__ characters. It changes when a rule changes, not when the product does.\n- **`docs/decisions/`** — one file per decision: context → decision → rationale → consequences, plus its line in the index. Written **when the decision is made**, never retrofitted. A correction is a dated block added in place, or a \"superseded by\" block naming what replaced it; **nothing is deleted**. An undocumented decision found in the code gets written up and flagged.\n- **`docs/design/`** is the plan and stays the plan. What actually happened goes to `docs/log/`.\n- **`docs/ROADMAP.md`** — the milestone ladder with honest status, and every **out-of-scope list intact**. Done items move to done; excluded items never silently vanish. Moving scope requires editing this file first, and only after the founder confirms.\n- **The environment example file** — every variable the typed config parses, one line of comment each, **placeholder values only**, kept in lockstep with the config.\n- **The README** — what and why in two sentences; a quickstart that is copy-paste runnable from a fresh clone, with the exact commands run before they are written down; the short architecture tree; the three or four choices that shaped the product, linking the index for the rest; and an honest status.\n\nReport as the contract says, saved to `<slice folder>/docs.md`. Lead with what you changed; then, separately, anything you found that documentation **cannot** fix: a broken quickstart, behaviour that looks unintended, a variable the code reads but the example omits, a decision made in code that nobody wrote down. ",
  "agents/implementer.md": "Read `.claude/agents/README.md` first: it is the contract.\n\nYou implement **one bounded slice**. Your brief is `brief.md` in the slice folder the lead names by absolute path: follow it exactly — the files and line ranges it names, not whole design docs. Also read your slice's section of the milestone plan and the decision entries that section cites.\n\n## How you build\n\n- Build the **smallest complete change**: everything the task needs and nothing it does not, in the surrounding idioms, editing rather than rewriting.\n- Respect the architecture: dependency direction inward, modules do not import each other, shared shapes do not fork, no business logic in route handlers, every inbound body parsed by a schema from the shared contracts package.\n- Work you notice but were not asked for goes in your report's \"found, not done\" list, never into the diff.\n\n## The rules you must never get wrong\n\n1. **Authentication goes through its port, untouched.** Never hand-roll a session, never compare identities outside the gate middleware. If your slice seems to need an auth change, **stop and report** — that is the lead's call plus a security audit, not yours.\n2. **Default-deny.** A new route is gated unless the plan explicitly lists it as public and you add it to the public list deliberately. The route-table backstop test must stay green: if it fails, fix the route, never the test.\n3. **Fail closed.** Blank configuration selects an adapter that refuses. Never a permissive stub, never a hardcoded fallback secret outside documented dev-only defaults.\n4. **Read-only ports stay read-only.** No writes, no schema copies, and the surface degrades gracefully rather than erroring when the external system is unreachable.\n\n## Tests ship with the change\n\n- Unit tests for pure logic against fakes; integration tests for adapters. Tests mirror the source tree — never colocated.\n- If your slice touches an exposed route, authentication, a personal-data surface or an external port, write the corresponding **mandatory test**: the gate, the default-deny backstop, fail-closed, the data-leak check, the dependency-down case. A slice touching those without its test is not done.\n- Test **behaviour, not framework internals**. No focused tests, no skipped tests.\n\n## Gates and report\n\n- **Run the full gate chain once, at the end**, as the contract's gates section lists it. While building, run only the affected tests. Never report a red tree as finished.\n- **Do not commit, push, open pull requests, switch branches or stash** unless the brief says so. Never touch the environment file; a new variable goes to the example file with a placeholder and into the typed config.\n- **Write control characters as escape sequences**, never raw bytes: git treats such a file as binary; and keep escape sequences out of shell command text.\n- Report as the contract says, saved to `<slice folder>/implementer.md`. Lead with the verdict (done or blocked), the must-fix issues you could not resolve and the calls that need a ruling; then files touched, tests added and what each proves, the gate results, **the lines the reviewer should plant** (the guards your tests claim to enforce), and what you deferred, guessed at, or disagree with in the plan.\n",
  "agents/reviewer.md": "Read `.claude/agents/README.md` first: it is the contract.\n\nYou **review** a change. You do **not** edit files — you critique, and you verify claims by running things yourself, never on faith.\n\nAlso read the builder's saved report beside the brief (`implementer.md` or `ui-engineer.md`) — never a pasted summary — then inspect the change with `git diff` and `git status` and read the files it touches.\n\nYou run **after** the security auditor, never beside it: you plant, it reads.\n\n## Check in this order, because the order is the priority\n\n1. **The exposed surface.** Every new or changed route: is it gated? Is anything added to the public list, and does the plan justify it? Does the default-deny backstop test still cover the new route table? Any change to the authentication or middleware surface is an automatic must-fix finding unless the task explicitly ordered it — and then it needs the security auditor, not just you.\n2. **Personal-data discipline.** Nothing the product holds on its owner belongs in a log, an error message, an error envelope, or a response that did not need it. Hunt for a log call carrying a whole document, and for typed errors that embed content in their message.\n3. **Does it do what was asked?** Edge cases, error handling, obvious bugs. Construct a concrete failing scenario for a suspected bug: inputs → wrong result. Check the slice's \"done when\" line from the plan is actually true.\n4. **Architecture.** Dependency direction, modules not importing each other, contracts not forked, inbound validation present, no logic in route handlers, secrets only on the server, external systems only behind their ports, fail-closed adapters for any new keyed dependency.\n5. **Tests.** Do they exist, do they test behaviour, do they actually pass? **Do not re-run the full gate chain** — the builder ran it and the lead runs it again at close. Run the suites your plants target, and any suite whose green you doubt. An exposed route with no unauthorised-access test is incomplete work.\n6. **Simplicity.** Over-built, duplicated, mis-named, an abstraction with one caller, a dependency that did not need adding, generality for users who will never exist.\n\n## Verify by planting\n\nA claim is verified by breaking it and watching a test go red. Plant a mutation — invert a guard, drop a filter, return the owner's identity — run the suite that should catch it, restore, and report the count.\n\nIf you need the plant rules, read `.claude/reference/plant.md`. Your own, on top of them:\n\n- **Snapshot before planting.** Copy every file a plant will touch to a fresh scratch directory outside the repository, plus a `sha256sum` manifest. Restore by copying back and confirm with `sha256sum -c`. **Never `git checkout -- <file>`** — it discards the slice's own uncommitted work.\n- The manifest covers every file a **plant** touches, not every file the slice touches. Re-snapshot only from a tree just verified green.\n- **Verify the plant landed in code, not in a comment**: grep the planted line back.\n- After the run, read `git diff` of the production tree yourself: a planted constant equal to the owner's identity is invisible to every test.\n- Prefer plants in production code: a plant in a test only proves the test can be silenced.\n- **A plant no gate caught is a finding about the gates, not a pass.** Say which gate is missing.\n- A gate that has stopped asserting is worse than no gate, because it reads as proof.\n- Run the formatter check before staging anything.\n\n## Report\n\nReport findings **most-severe first**, each as: the problem · a concrete failure or why it matters · a suggested fix. Distinguish **must-fix** from **nice-to-have** explicitly. If the change is genuinely clean, say so plainly — **do not invent nits**.\n\nReport as the contract says, saved to `<slice folder>/review.md`. Lead with the one-line **verdict: `approve` or `revise`** and the must-fix findings with `file:line`; follow-ups are a count; then the plant table (plant · file · red count · `sha256sum -c` result) with the tally planted · caught · by which gate · **which ones only a reader could catch**; end with calls needing a ruling.\n",
  "agents/security-auditor.md": "Read `.claude/agents/README.md` first: it is the contract.\n\nYou **audit** __MKTRUE_NAME__ defensively. __MKTRUE_STAKES__ You critique and verify by running things; you do not edit files.\n\n**You run only when the slice is triggered**, by the list in rule 5 of the loop contract: __MKTRUE_AUDIT_TRIGGERS__. You verify by probing: construct the request, walk the route table, run the one test that proves a claim. You do **not** re-run the full gate chain, and you never run beside the reviewer.\n\nTold a diff, audit the diff plus the surfaces it touches. Told the repository, audit the whole thing. Also read the builder's saved report beside the brief and the decision entries the diff or its plan cites — not the whole folder. Then check **in priority order**:\n\n1. **The gate.** Every route refuses without proof of being the owner, unless its method and path are deliberately on the public list. Walk the route table yourself and try to construct the unauthenticated request that reads something private. Check the backstop test still covers every registered route. Credentials must be **verified** server-side through their port, never decoded and trusted; no client-supplied identity ever matters. Null adapters fail **closed**, not open. Any diff touching the authentication or middleware surface gets line-by-line scrutiny: a change there is either explicitly ordered or a **critical** finding by itself.\n\n2. **The data this product holds:** __MKTRUE_DATA_CLASSES__. Never in logs, never in error messages or the error envelope, never in analytics, never in a response that did not need it, never in a URL or query string. Deleting must actually delete. Backups count as the same data: flag any backup path that copies it somewhere readable.\n\n3. **Secrets.** Environment-only, the environment file git-ignored, the example file carrying placeholders only, and **nothing in the git history** — check suspect paths with `git log -p`. A secret in history means *rotate and clean*: say so explicitly. Public-prefixed variables only for genuinely public values.\n\n4. **Input trust and injection.** Every inbound body and parameter validated against the shared schema before use. Datastore filters built from **validated scalar fields** — never a raw client object spread into a query. Unbounded patterns from user input, and unvalidated sort, limit or range parameters that enable resource exhaustion.\n\n5. **External seams.** Anything behind a port that holds a credential follows the same environment-only rules. A read-only port must never write: flag any call that could. Flag assumptions that would break if the far side started returning something hostile. Where external text can reach a tool call that writes, deletes or sends, **prompt injection is in scope**.\n\n6. **Client surface.** Caches must never hold authenticated responses or anything private. Security headers present, cross-origin policy not wide open, user-authored text sanitised wherever it is rendered. Stored script injection counts, even with one user.\n\n7. **Operational abuse.** Public endpoints have body-size limits and rate limits. No stack traces or datastore errors to clients. Health endpoints reveal version only — never configuration, never counts of anything personal.\n\n8. **Dependencies and supply chain.** Run the audit tool and report real findings, not noise. Any new dependency is warranted, maintained and lockfile-pinned; check install scripts before letting a package run code at install time. Images and base layers pinned to an exact patch — a floating tag is a finding.\n\n## How you judge\n\n- **Never appeal to a control the system does not have.** \"An attacker would need an account\" is not a mitigation in a product that has no accounts.\n- The question behind every finding, however small the surface: *what would a compromise of this reach?*\n\nReport as the contract says, saved to `<slice folder>/audit.md`. Lead with the verdict, **safe to merge** or **blocked by: <list>**, then critical and high findings with `file:line`, each with a concrete abuse scenario, the fix direction, and **confirmed** or **needs verification**; medium and below one line each, notes a count; then the lines the reviewer should plant and the calls needing a ruling. If the surface is genuinely clean, say so — no invented findings.\n",
  "agents/ui-engineer.md": "Read `.claude/agents/README.md` first: it is the contract.\n\nYou own the interface of __MKTRUE_NAME__. One audience, one test it must survive: __MKTRUE_AUDIENCE_TEST__\n\nYour brief is `brief.md` in the slice folder the lead names by absolute path; also read the plan sections your slice cites.\n\n## The design rules\n\n- **Mobile-first is literal.** Design at 360px, then let it breathe upward. The desktop layout is the adaptation, not the other way round. Test every slice at 360px before reporting done.\n- **Capture beats consumption.** The most common action is reachable in two taps from open, and never behind a scroll. Prefer one-tap inputs over free text; free text is optional, never required to save.\n- **Pre-fill from what the system already knows.** A form that shows what today already contains is a confirmation, not a blank page. Empty states name the one action that fills them.\n- **State is never ambiguous.** A failed save says so loudly and **keeps the input** — it never silently discards typed work. Optimistic updates must not fabricate a write that has not landed.\n- **Charts answer a question.** Every chart states its question. If it needs a wide desktop to read, redesign it. No chart of data the viewer cannot act on.\n- **Take every colour, size, spacing step and radius from the token file.** A raw value in a component is a defect. Never introduce a token the product does not already own.\n- **Polish is a feature, but it never delays usable.** Ship the working screen; log the sparkle as deferred.\n\n## Craft baseline\n\n- Accessible by default: semantic elements, real labels, keyboard operable, visible focus, roles only when semantics cannot do the job. Never a generic element where a button belongs. Touch targets at least 44px.\n- Server-rendered by default; client interactivity only where it is required. Data fetching and secrets stay on the server.\n- Every string a person reads comes from the translation files, in every one of: __MKTRUE_LANGUAGES__. No string is hardcoded in a component, and no language is left behind when another gains one.\n- Component tests assert behaviour — a form validates, a filter filters — not markup snapshots.\n- Caches must never hold anything private.\n\nReport as the contract says, saved to `<slice folder>/ui-engineer.md`. Lead with the verdict, unresolved must-fix issues and calls needing a ruling; then what you built, the states you covered (loading, empty, error, offline), how you verified it including at 360px, the lines the reviewer should plant, and any place the design fought the data model — that is usually an architect problem, so name it rather than working around it.\n",
  "bench.json": "{\n  \"schema\": 1,\n  \"version\": \"1.1.1\",\n  \"slotSyntax\": \"__MKTRUE_<KEY>__\",\n  \"slots\": {\n    \"NAME\": {\n      \"from\": \"answers.name\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"PURPOSE\": {\n      \"from\": \"answers.purpose\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"OWNER\": {\n      \"from\": \"answers.owner\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"AUDIENCE_TEST\": {\n      \"from\": \"answers.audienceTest\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"STAKES\": {\n      \"from\": \"answers.stakes\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"DATA_CLASSES\": {\n      \"from\": \"answers.dataClasses\",\n      \"required\": true,\n      \"kind\": \"list\",\n      \"empty\": \"nothing sensitive\"\n    },\n    \"AUTH\": {\n      \"from\": \"answers.auth\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"LANGUAGES\": {\n      \"from\": \"answers.languages\",\n      \"required\": true,\n      \"kind\": \"list\"\n    },\n    \"GATES\": {\n      \"from\": \"derived.gates\",\n      \"required\": true,\n      \"kind\": \"list\"\n    },\n    \"AUDIT_TRIGGERS\": {\n      \"from\": \"config.auditTriggers\",\n      \"required\": true,\n      \"kind\": \"list\"\n    },\n    \"BASE_BRANCH\": {\n      \"from\": \"config.baseBranch\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"BUDGET_RULES\": {\n      \"from\": \"config.budgets.rules\",\n      \"required\": true,\n      \"kind\": \"number\"\n    },\n    \"BUDGET_STATE\": {\n      \"from\": \"config.budgets.state\",\n      \"required\": true,\n      \"kind\": \"number\"\n    },\n    \"BUDGET_DECISION\": {\n      \"from\": \"config.budgets.decision\",\n      \"required\": true,\n      \"kind\": \"number\"\n    },\n    \"KIT_VERSION\": {\n      \"from\": \"derived.kitVersion\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"TEMPLATE\": {\n      \"from\": \"derived.template\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"TEMPLATE_VERSION\": {\n      \"from\": \"derived.templateVersion\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"DATE\": {\n      \"from\": \"derived.date\",\n      \"required\": true,\n      \"kind\": \"text\"\n    },\n    \"ROLE_ID\": {\n      \"from\": \"derived.roleId\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"COMMAND_ID\": {\n      \"from\": \"derived.commandId\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"REFERENCE_ID\": {\n      \"from\": \"derived.referenceId\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"PATH_STATE\": {\n      \"from\": \"config.paths.state\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"PATH_ROADMAP\": {\n      \"from\": \"config.paths.roadmap\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"PATH_DECISIONS_INDEX\": {\n      \"from\": \"config.paths.decisionsIndex\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"PATH_DECISIONS\": {\n      \"from\": \"config.paths.decisions\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"PATH_DESIGN\": {\n      \"from\": \"config.paths.design\",\n      \"required\": true,\n      \"kind\": \"path\"\n    },\n    \"PATH_LOG\": {\n      \"from\": \"config.paths.log\",\n      \"required\": true,\n      \"kind\": \"path\"\n    }\n  },\n  \"roles\": [\n    {\n      \"id\": \"architect\",\n      \"title\": \"Architect\",\n      \"body\": \"agents/architect.md\",\n      \"description\": \"Use at the start of a milestone, or when a change spans more than one boundary, to get the milestone plan and its kickoff page in docs/design/; it never writes production code.\",\n      \"tools\": [\"Read\", \"Write\", \"Edit\", \"Bash\", \"Grep\", \"Glob\"],\n      \"model\": \"opus\",\n      \"effort\": \"xhigh\",\n      \"slots\": [\"NAME\", \"PURPOSE\"],\n      \"report\": \"<main checkout>/.mktrue/slices/<milestone>-kickoff/architect.md\"\n    },\n    {\n      \"id\": \"implementer\",\n      \"title\": \"Implementer\",\n      \"body\": \"agents/implementer.md\",\n      \"description\": \"Use when a slice's brief is written and its surface is not the interface, to build the change with its tests and one full gate run; it never commits, pushes or opens a pull request.\",\n      \"tools\": [\"Read\", \"Write\", \"Edit\", \"Bash\", \"Grep\", \"Glob\"],\n      \"model\": \"opus\",\n      \"effort\": \"high\",\n      \"slots\": [],\n      \"report\": \"<slice folder>/implementer.md\"\n    },\n    {\n      \"id\": \"ui-engineer\",\n      \"title\": \"UI engineer\",\n      \"body\": \"agents/ui-engineer.md\",\n      \"description\": \"Use when a slice's surface is the interface (screens, charts, theming, accessibility, responsive or offline behaviour), to build it and verify it at 360px; it never hardcodes a string or a raw design value.\",\n      \"tools\": [\"Read\", \"Write\", \"Edit\", \"Bash\", \"Grep\", \"Glob\"],\n      \"model\": \"opus\",\n      \"effort\": \"high\",\n      \"slots\": [\"NAME\", \"AUDIENCE_TEST\", \"LANGUAGES\"],\n      \"report\": \"<slice folder>/ui-engineer.md\"\n    },\n    {\n      \"id\": \"security-auditor\",\n      \"title\": \"Security auditor\",\n      \"body\": \"agents/security-auditor.md\",\n      \"description\": \"Use before merging a slice whose diff touches a trigger surface, to get findings ranked by severity and a safe-to-merge or blocked verdict; it is read-only and never writes exploits.\",\n      \"tools\": [\"Read\", \"Grep\", \"Glob\", \"Bash\"],\n      \"model\": \"opus\",\n      \"effort\": \"high\",\n      \"slots\": [\"NAME\", \"STAKES\", \"DATA_CLASSES\", \"AUDIT_TRIGGERS\"],\n      \"report\": \"<slice folder>/audit.md\"\n    },\n    {\n      \"id\": \"reviewer\",\n      \"title\": \"Reviewer\",\n      \"body\": \"agents/reviewer.md\",\n      \"description\": \"Use after a slice is built, and after its audit if one ran, to get findings ranked by severity, verified by planting deliberate bugs, and an approve or revise verdict; it never edits a file.\",\n      \"tools\": [\"Read\", \"Bash\", \"Grep\", \"Glob\"],\n      \"model\": \"opus\",\n      \"effort\": \"high\",\n      \"slots\": [],\n      \"report\": \"<slice folder>/review.md\"\n    },\n    {\n      \"id\": \"docs-writer\",\n      \"title\": \"Docs writer\",\n      \"body\": \"agents/docs-writer.md\",\n      \"description\": \"Use at a milestone boundary, or whenever behaviour has drifted from what the docs claim, to bring the README, the decision index, plans, the roadmap, the environment example and docs/STATE.md back to the truth; it never documents what does not exist.\",\n      \"tools\": [\"Read\", \"Write\", \"Edit\", \"Bash\", \"Grep\", \"Glob\"],\n      \"model\": \"sonnet\",\n      \"effort\": \"low\",\n      \"slots\": [\"NAME\", \"OWNER\", \"BUDGET_STATE\", \"BUDGET_RULES\"],\n      \"report\": \"<slice folder>/docs.md\"\n    }\n  ],\n  \"contracts\": [\n    {\n      \"id\": \"loop-contract\",\n      \"title\": \"The loop contract\",\n      \"body\": \"loop-contract.md\",\n      \"renderTo\": \".claude/agents/README.md\",\n      \"slots\": [\"AUDIT_TRIGGERS\", \"GATES\"]\n    }\n  ],\n  \"commands\": [\n    {\n      \"id\": \"start-milestone\",\n      \"title\": \"Start a milestone\",\n      \"body\": \"commands/start-milestone.md\",\n      \"slots\": []\n    },\n    {\n      \"id\": \"brief\",\n      \"title\": \"Write the brief\",\n      \"body\": \"commands/brief.md\",\n      \"slots\": [\"AUDIT_TRIGGERS\"]\n    },\n    {\n      \"id\": \"start-slice\",\n      \"title\": \"Start a slice\",\n      \"body\": \"commands/start-slice.md\",\n      \"slots\": [\"AUDIT_TRIGGERS\"]\n    },\n    {\n      \"id\": \"close-slice\",\n      \"title\": \"Close a slice\",\n      \"body\": \"commands/close-slice.md\",\n      \"slots\": [\"GATES\", \"BUDGET_STATE\", \"BASE_BRANCH\"]\n    },\n    {\n      \"id\": \"new-module\",\n      \"title\": \"Scaffold a module\",\n      \"body\": \"commands/new-module.md\",\n      \"slots\": []\n    },\n    {\n      \"id\": \"create-roadmap\",\n      \"title\": \"Create the roadmap\",\n      \"body\": \"commands/create-roadmap.md\",\n      \"slots\": [\"BUDGET_STATE\"]\n    },\n    {\n      \"id\": \"update-roadmap\",\n      \"title\": \"Update the roadmap\",\n      \"body\": \"commands/update-roadmap.md\",\n      \"slots\": [\"BUDGET_STATE\"]\n    }\n  ],\n  \"references\": [\n    {\n      \"id\": \"plant\",\n      \"title\": \"Plant a bug\",\n      \"body\": \"references/plant.md\",\n      \"slots\": []\n    },\n    {\n      \"id\": \"worktree\",\n      \"title\": \"Work in a worktree\",\n      \"body\": \"references/worktree.md\",\n      \"slots\": [\"BASE_BRANCH\"]\n    }\n  ],\n  \"workflows\": [\n    {\n      \"id\": \"mktrue\",\n      \"title\": \"The kit's check, on every push\",\n      \"body\": \"workflows/mktrue.yml\",\n      \"renderTo\": \".github/workflows/mktrue.yml\",\n      \"slots\": [\"KIT_VERSION\"]\n    }\n  ],\n  \"rules\": [\n    {\n      \"section\": 1,\n      \"title\": \"Where to look first\",\n      \"body\": \"rules/01-where-to-look-first.md\",\n      \"owner\": \"kit\",\n      \"slots\": [\n        \"NAME\",\n        \"PURPOSE\",\n        \"KIT_VERSION\",\n        \"PATH_STATE\",\n        \"PATH_ROADMAP\",\n        \"PATH_DECISIONS_INDEX\",\n        \"PATH_DECISIONS\",\n        \"PATH_DESIGN\",\n        \"PATH_LOG\"\n      ]\n    },\n    {\n      \"section\": 2,\n      \"title\": \"Stack and versions\",\n      \"body\": \"rules/02-stack-and-versions.md\",\n      \"owner\": \"repo\",\n      \"slots\": []\n    },\n    {\n      \"section\": 3,\n      \"title\": \"Architecture and boundaries\",\n      \"body\": \"rules/03-architecture-and-boundaries.md\",\n      \"owner\": \"repo\",\n      \"slots\": []\n    },\n    {\n      \"section\": 4,\n      \"title\": \"How work runs\",\n      \"body\": \"rules/04-how-work-runs.md\",\n      \"owner\": \"repo\",\n      \"slots\": [\"GATES\"]\n    },\n    {\n      \"section\": 5,\n      \"title\": \"Testing and plants\",\n      \"body\": \"rules/05-testing-and-plants.md\",\n      \"owner\": \"repo\",\n      \"slots\": []\n    },\n    {\n      \"section\": 6,\n      \"title\": \"Security posture and data classes\",\n      \"body\": \"rules/06-security-and-data-classes.md\",\n      \"owner\": \"repo\",\n      \"slots\": [\"DATA_CLASSES\", \"AUTH\", \"AUDIT_TRIGGERS\"]\n    },\n    {\n      \"section\": 7,\n      \"title\": \"Conventions\",\n      \"body\": \"rules/07-conventions.md\",\n      \"owner\": \"repo\",\n      \"slots\": [\"LANGUAGES\"]\n    },\n    {\n      \"section\": 8,\n      \"title\": \"What agents may and may not do\",\n      \"body\": \"rules/08-agent-permissions.md\",\n      \"owner\": \"repo\",\n      \"slots\": []\n    },\n    {\n      \"section\": 9,\n      \"title\": \"Budgets and drift\",\n      \"body\": \"rules/09-budgets-and-drift.md\",\n      \"owner\": \"repo\",\n      \"slots\": [\"BUDGET_RULES\", \"BUDGET_STATE\", \"BUDGET_DECISION\"]\n    },\n    {\n      \"section\": 10,\n      \"title\": \"Where things live\",\n      \"body\": \"rules/10-where-things-live.md\",\n      \"owner\": \"repo\",\n      \"slots\": []\n    }\n  ],\n  \"docs\": [\n    {\n      \"id\": \"state\",\n      \"title\": \"State\",\n      \"body\": \"docs/state.md\",\n      \"renderTo\": \"docs/STATE.md\",\n      \"slots\": [\"NAME\"]\n    },\n    {\n      \"id\": \"design-plan\",\n      \"title\": \"Milestone plan\",\n      \"body\": \"docs/design-plan.md\",\n      \"renderTo\": \"docs/design/\",\n      \"slots\": []\n    },\n    {\n      \"id\": \"decision\",\n      \"title\": \"Decision\",\n      \"body\": \"docs/decision.md\",\n      \"renderTo\": \"docs/decisions/\",\n      \"slots\": [\"BUDGET_DECISION\"]\n    },\n    {\n      \"id\": \"log-entry\",\n      \"title\": \"Log entry\",\n      \"body\": \"docs/log-entry.md\",\n      \"renderTo\": \"docs/log/\",\n      \"slots\": []\n    },\n    {\n      \"id\": \"created-log\",\n      \"title\": \"The created log\",\n      \"body\": \"docs/created.md\",\n      \"renderTo\": \"docs/log/\",\n      \"slots\": [\n        \"NAME\",\n        \"DATE\",\n        \"KIT_VERSION\",\n        \"TEMPLATE\",\n        \"TEMPLATE_VERSION\",\n        \"PURPOSE\",\n        \"OWNER\",\n        \"AUTH\",\n        \"LANGUAGES\",\n        \"DATA_CLASSES\",\n        \"GATES\"\n      ]\n    },\n    {\n      \"id\": \"roadmap\",\n      \"title\": \"Roadmap\",\n      \"body\": \"docs/roadmap.md\",\n      \"renderTo\": \"docs/ROADMAP.md\",\n      \"slots\": [\"NAME\"]\n    },\n    {\n      \"id\": \"decisions-index\",\n      \"title\": \"Decisions index\",\n      \"body\": \"docs/decisions-index.md\",\n      \"renderTo\": \"docs/decisions/index.md\",\n      \"slots\": []\n    },\n    {\n      \"id\": \"design-readme\",\n      \"title\": \"Design\",\n      \"body\": \"docs/design-readme.md\",\n      \"renderTo\": \"docs/design/README.md\",\n      \"slots\": []\n    }\n  ],\n  \"targets\": {\n    \"claude-code\": {\n      \"roles\": \".claude/agents/__MKTRUE_ROLE_ID__.md\",\n      \"commands\": \".claude/commands/__MKTRUE_COMMAND_ID__.md\",\n      \"references\": \".claude/reference/__MKTRUE_REFERENCE_ID__.md\",\n      \"rules\": \"CLAUDE.md\",\n      \"settings\": \".claude/settings.json\",\n      \"settingsBody\": \"settings/claude-code.json\",\n      \"roleFrontmatter\": [\"name\", \"description\", \"tools\", \"model\", \"effort\"],\n      \"vocabulary\": {\n        \"models\": [\"opus\", \"sonnet\", \"haiku\", \"inherit\"],\n        \"efforts\": [\"low\", \"medium\", \"high\", \"xhigh\", \"max\"],\n        \"effortUnsupportedOn\": [\"haiku\"]\n      }\n    }\n  }\n}\n",
  "commands/brief.md": "# Write the brief\n\nThe leg work before a slice: place it, make its folder, write its brief, decide its audit. Do the steps in order.\n\n## 1 · Place the slice\n\nRead `docs/STATE.md` and the plan section for this slice. If the slice still has an open question for the founder, **stop**: it belongs on the milestone's kickoff page, not in this slice.\n\nBranch in the main checkout if you are working alone, otherwise work in a worktree. If you need the worktree rules, read `.claude/reference/worktree.md`.\n\n## 2 · Make the slice folder\n\nThe slice folder is `<main checkout>/.mktrue/slices/<slice-id>`. The main checkout is the directory that holds the repository's `.git` directory, so every worktree shares the folder. Find it:\n\n```\ngit rev-parse --path-format=absolute --git-common-dir\n```\n\nThat prints `<main checkout>/.git`. Drop the trailing `.git`, write the slice folder out as an absolute path, and make it with that path typed in full:\n\n```\nmkdir -p <main checkout>/.mktrue/slices/<slice-id>\n```\n\nIf the printed path does not end in `/.git` (a submodule or a bare layout), keep the slice folder at `<working tree root>/.mktrue/slices/<slice-id>/` instead; `mktrue audit` then attributes by the old rule only.\n\nEvery later step and every agent prompt uses that absolute path, never a shell variable. The folder is never committed and never scanned by the prose budgets: `.gitignore` must hold the line `.mktrue/`. Add it if the repository lacks it.\n\n## 3 · Write `<slice folder>/brief.md`\n\nFixed sections: **Rulings · Shape · Must hold · Tests and plants · Audit · Reports**.\n\nName line ranges, not whole documents. Name the plants up front. Leave out history the agent can read in the report it is told to open. State the working directory as an absolute path, and say plainly: no commit, push, branch switch or stash unless told.\n\n## 4 · Decide the audit now\n\nThe security auditor runs when the slice touches any of: __MKTRUE_AUDIT_TRIGGERS__. Write the decision into the brief either way — if it does not run, the brief says so and why.\n\nStop here. Running the agents is `/start-slice`.\n",
  "commands/close-slice.md": "# Close a slice\n\nGates, merge, the merge confirmed, state replaced. **Do the steps in order; do not skip one because it obviously passed.**\n\n## 1 · The tree is yours and clean of plants\n\n`git status`. Confirm no agent is still running. Verify the reviewer's snapshot manifest with `sha256sum -c`. Run the formatter check.\n\n## 2 · The authoritative gate run\n\nRun the chain **package by package, in the foreground**, never as one parallel run: __MKTRUE_GATES__\n\nA red count **or a skipped count** is a stop, not a caveat: re-run that suite alone before believing either. If a step is killed under memory pressure, re-run only the steps that had not passed, with a larger heap. **These are the only numbers quoted anywhere** — not the agents'.\n\n## 3 · The canonical record\n\nWrite `<slice folder>/record.md`, from the reports you saved there: what landed · the rulings made · the audit verdict, or \"not triggered, because …\" · the plant table · the close-run numbers · what is owed to the founder.\n\nThe pull request body, the board entry and the log entry are all derived from this file, never written separately.\n\n## 4 · Pull request and merge\n\nOpen it against __MKTRUE_BASE_BRANCH__, passing long text with `--body-file` rather than inline. Check CI with a **short poll** whose exit code you inspect — never a long-lived background watcher, and never piped into a merge chain. No verdict, no merge.\n\nMerge, then **read the result before anything else**:\n\n```\ngh pr view <number> --json state --jq .state\n```\n\nIt must print `MERGED`. Anything else — `OPEN`, `CLOSED`, an error — means the merge was refused: **stop the close here, with the branch and the worktree intact**, and fix what refused it.\n\n## 5 · Replace `docs/STATE.md`\n\nFrom the record, not from memory. **Replaced, never appended.** Under __MKTRUE_BUDGET_STATE__ characters. A settled decision's own file and its index line exist before this step.\n\n## 6 · Leave the tree\n\nOnly after step 4 printed `MERGED`: delete the branch, remove the worktree, keep the slice folder until the milestone closes. Then clear the session: the next slice starts from `docs/STATE.md`.\n\n## Done when\n\nGates green, `mktrue check` exit 0, the pull request's state read as `MERGED`, state replaced, worktree gone.\n",
  "commands/create-roadmap.md": "# Create the roadmap\n\nThe first command after `mktrue new`. It turns the founder's description of the product into a milestone ladder, confirmed before a line of it is written.\n\n## When\n\nOnce, while `docs/ROADMAP.md` lists no milestones. If it lists any, stop: from then on scope moves only through `/update-roadmap`.\n\n## Steps\n\n1. **Ask for the features, in detail, in one message.** Ask the founder to describe every feature the product should eventually have, and for each one:\n   - **What someone can do with it**, in their own words: \"I can see where last month's money went, from my phone.\"\n   - **Who** does it, and how often.\n   - **What data** it reads or keeps, and whether any of it is personal.\n   - **How much it matters**: needed for the first real use, needed soon after, or someday.\n   - **What it depends on**: another feature, an outside service, a sign-in.\n   - **How they would know it works**, tried by hand on a real device.\n\n   Take the answer in any shape: a list, prose, a pasted document. Then stop and wait. Nothing is drafted from a guess.\n\n2. **Close the gaps in one round.** Read the whole description, then ask every remaining question at once: a feature too vague to place, two that conflict, one with no way to know it works. Never trickle questions. If nothing is unclear, skip this step.\n\n3. **Run the architect** to write the draft to `docs/design/roadmap.md`:\n   - **A feature table.** Each feature gets an id (F1, F2, …), the founder's own sentence, its priority and what it depends on.\n   - **Milestones.** Each has a goal in the owner's terms, the feature ids it delivers, and a done-when the founder can check by hand on a device. Milestone 1 is the smallest thing the founder would actually use, and every milestone ends usable.\n   - **The order.** Dependencies first, then value, then risk. The riskiest unknown goes early, never last.\n   - **Out of scope.** Every \"someday\" feature and everything the founder excluded, each with the trigger that would bring it back.\n   - **A size for each milestone**, in one-evening slices, derived from its features and labelled an estimate.\n   - **Open calls.** Every question the ladder turns on (an order, a cut, a dependency on an outside service), each with options, their costs and a recommendation.\n\n4. **Check coverage before showing it.** Every feature id appears in exactly one milestone or in out of scope. A feature that silently vanished is the defect this command exists to prevent. A feature the founder never described is the other.\n\n5. **Publish the draft and its open calls as one decision page**, then stop. The founder answers it in one sitting.\n\n6. **When it comes back answered:**\n   - Write `docs/ROADMAP.md` from the confirmed draft: the milestone table, every status `planned`, each done-when as confirmed, and the out-of-scope list.\n   - Record the ladder as a decision file, with its line in the index.\n   - Replace `docs/STATE.md`, under __MKTRUE_BUDGET_STATE__ characters, so that it names `/start-milestone` for milestone 1 as the next step.\n\n## Rules\n\n- Nothing is built during this command: no code, and no milestone plan. Planning a milestone is `/start-milestone`.\n- The founder's words are the source. The architect may split, merge or reorder features, and says where it did. It never adds one.\n- Priorities and done-whens belong to the founder. Where the architect proposes one, the page marks it as proposed.\n\n## Done when\n\n`docs/ROADMAP.md` lists every confirmed milestone with a done-when checkable on a device, every described feature sits in a milestone or in out of scope, the ladder has a decision file, and `docs/STATE.md` names milestone 1 as next.\n",
  "commands/new-module.md": "# Scaffold a module\n\nA new bounded module is a real event, not a routine scaffold.\n\n## Preconditions\n\n1. **The module is the current milestone in `docs/ROADMAP.md`.** If it is not, stop — adding a module the roadmap does not call for is exactly the scope creep the rules forbid.\n2. **State in one sentence why the work does not belong in an existing module.** If you cannot, stop.\n\n## Steps\n\n1. **Design first.** Delegate to the **architect** to produce the plan section for this module, and **stop there**. The founder answers the design questions before any scaffolding happens.\n2. **Scaffold only the layers the plan earns.** No empty folders for symmetry.\n3. Add the shared shapes to the contracts package. A second copy of a schema anywhere else is a fork.\n4. Add the routes. **Every route is gated by default** unless the plan explicitly lists it public. Verify the route-table backstop test picks the new routes up.\n5. Mirror the test tree, **including the unauthorised-access test** and the mandatory test classes the new surface touches.\n6. Run the affected tests, the type check and the linter — not the full chain.\n\n## Done when\n\nThe module exists with the layers its plan earned, its routes are gated and covered by the backstop, and its mandatory tests pass.\n",
  "commands/start-milestone.md": "# Start a milestone\n\nThe kickoff. One plan, one kickoff page, answered in one sitting.\n\n## Steps\n\n1. Read `docs/STATE.md` and `docs/ROADMAP.md`. If the roadmap lists no milestones, stop and run `/create-roadmap` first: a milestone the roadmap does not name has nothing to be measured against.\n2. Run the **architect**. It writes the milestone plan to `docs/design/<milestone>.md` and the kickoff page to `docs/design/<milestone>-kickoff.md`. The page lives under `docs/design/`, never `docs/decisions/`. Save its report as rule 2 of `.claude/agents/README.md` says, verbatim to `<main checkout>/.mktrue/slices/<milestone>-kickoff/architect.md`, a folder you make as `/brief` step 2 makes a slice folder. Never save it under `docs/design/`: a report is not a design.\n3. Stop. Hand the kickoff page to the founder and wait.\n4. When it comes back answered, split it: one file per decision under `docs/decisions/`, each with its own number, and one line per decision in `docs/decisions/index.md`. The kickoff page stays where it is, as the record of what was asked.\n5. Freeze the plan. Record the slice list in `docs/STATE.md`.\n\n## Rules\n\n- The plan is not frozen until every question on the page has an answer. A question answered later is a new decision file, not an edit to a frozen plan.\n- Questions do not trickle out across the milestone. If a slice raises a genuinely new one, it goes to the founder as a decision file, and the fact that the kickoff missed it goes in the log.\n- Nothing is built during kickoff.\n\n## Done when\n\nThe plan is frozen, every decision has a file, and `docs/STATE.md` names the first slice.\n",
  "commands/start-slice.md": "# Start a slice\n\nFrom a written brief to a reviewed change. Read `<slice folder>/brief.md`; if there is none, run `/brief` first. Do the steps in order.\n\n## 1 · Run the agents one at a time, each spawned fresh\n\n`implementer` or `ui-engineer` → `security-auditor` **if triggered** → `reviewer`.\n\nSave each report as rule 2 of `.claude/agents/README.md` says, before you spawn the next agent. Each agent reads the earlier saved reports, **never a summary you paste**. The auditor and the reviewer never run at once, and no finished agent is resumed (rule 3 of `.claude/agents/README.md`).\n\n**When the auditor runs**, its scope is the branch diff against its base plus anything uncommitted, unless the brief says otherwise; say which it is. **Do not pre-filter what it sees.** Then triage its report:\n\n- Anything touching a trigger surface — __MKTRUE_AUDIT_TRIGGERS__ — is **must-fix before merge**, no exceptions. Rank the rest honestly; do not inflate notes into blockers.\n- A bounded fix goes to the implementer as a follow-up (step 2). Anything structural is written up as a decision question for the founder, never improvised as a security design mid-review.\n- If the audit found a class of bug worth preventing, propose the **mandatory-test addition** to the rules rather than only fixing the instance.\n- The verdict and its findings go into the slice record. Every critical and high finding is fixed or has an explicit ruling.\n\n## 2 · Follow-ups are new agents\n\nAppend a `## Follow-up <n>` section to the brief with the saved report paths, and spawn a fresh agent against it.\n\n## 3 · On an `approve` verdict\n\nRun `/close-slice`.\n\n## Done when\n\nThe brief has a saved report beside it for every agent that ran, every audit finding is triaged, the reviewer found no surviving plants, and the change is ready to close.\n",
  "commands/update-roadmap.md": "# Update the roadmap\n\nThis command is the **only sanctioned way scope moves**.\n\n## Steps\n\n1. **Establish what actually exists.** Read the recent commit log, the roadmap and `docs/STATE.md`. The update describes **reality, not intention** — if a slice is half done, it says which half.\n2. **Update the roadmap.** Mark what is done, and check each done milestone's acceptance criteria, in the owner's terms. **Keep every milestone's out-of-scope list intact**: done items move to done, excluded items never silently vanish.\n3. **Process any scope change.** Apply it **only after the founder confirms**, and record it as its own decision file with a line in the index.\n4. **Replace `docs/STATE.md`** — never append. Under __MKTRUE_BUDGET_STATE__ characters.\n\n## Done when\n\nThe roadmap matches reality, every scope change has a decision file, and the state file is replaced and inside its budget.\n",
  "docs/created.md": "# __MKTRUE_NAME__ created · __MKTRUE_DATE__\n\nmktrue __MKTRUE_KIT_VERSION__ made this repository from the `__MKTRUE_TEMPLATE__` template, version __MKTRUE_TEMPLATE_VERSION__.\n\n## What it was told\n\n- **Name:** __MKTRUE_NAME__\n- **Purpose:** __MKTRUE_PURPOSE__\n- **Owner:** __MKTRUE_OWNER__\n- **Sign-in:** __MKTRUE_AUTH__\n- **Languages:** __MKTRUE_LANGUAGES__\n- **Data it holds:** __MKTRUE_DATA_CLASSES__\n\nThese answers shaped the tree. They are kept in `.mktrue.json`, and `mktrue sync` renders from them.\n\n## Gates\n\nThe gates `new` runs before the first commit, in this order: __MKTRUE_GATES__\n\n## Next\n\nRun `/create-roadmap` in your agent. It writes the roadmap and the first state.\n",
  "docs/decision.md": "# <n> · <the decision, as a statement>\n\n<date> · decided\n\n<!-- One decision per file, at most __MKTRUE_BUDGET_DECISION__ characters. A decision recorded is never argued again. -->\n\n## The question\n\nWhat had to be decided, and what was blocked until it was.\n\n## Options weighed\n\n| Option | For | Against |\n| --- | --- | --- |\n\n## The choice\n\nWhat was chosen, and the one reason that settled it.\n\n## What follows\n\nWhat this makes true, and what it rules out. Anything that must change if this is ever reversed.\n",
  "docs/decisions-index.md": "# Decisions\n\n<!-- One line per decision, added when it is made. The decision itself is its own file beside this one. -->\n\n| # | Decision | Date |\n| --- | --- | --- |\n",
  "docs/design-plan.md": "# <milestone or slice>\n\n<date> · frozen when the milestone starts\n\n## What this delivers\n\nOne paragraph. What is true at the end that is not true now.\n\n## Slices\n\n| # | Slice | Done when |\n| --- | --- | --- |\n\n## Deliberately out of scope\n\nWhat this milestone will not do, so nobody plans as though it might.\n\n## Decisions this cites\n\n- `docs/decisions/<n>-<slug>.md`\n\n## How it will be proved\n\nThe gates, the plants, and the human check at the end.\n",
  "docs/design-readme.md": "# Design\n\n<!-- One plan per milestone, frozen when the work starts. What actually happened goes to docs/log/, never back into the plan. -->\n",
  "docs/log-entry.md": "# <slice> · <date>\n\n<!-- What actually happened. Nobody reads this in a hurry; write it for the person who needs it in six months. -->\n\n## What changed\n\nFiles touched, and what each change does.\n\n## Gates\n\nThe output, verbatim. Not a summary of it.\n\n## Plants\n\n| Plant | Caught | Note |\n| --- | --- | --- |\n\n## Found, not done\n\nWork noticed during the slice and deliberately left. Each line is a candidate for the next brief.\n",
  "docs/roadmap.md": "# Roadmap\n\n__MKTRUE_NAME__ · the milestone ladder\n\n<!-- Status is honest, and every out-of-scope line stays. Scope moves only after the owner confirms, and this file changes first. -->\n\n## Milestones\n\n| # | Milestone | Done when | Status |\n| --- | --- | --- | --- |\n\n## Out of scope\n\nWhat this product will not do. A line leaves this list only by a decision.\n",
  "docs/state.md": "# State\n\n__MKTRUE_NAME__ · <milestone> · <date>\n\n<!-- Replaced at every close. Never appended to. History lives in docs/log/. -->\n\n- Where the product stands, in a handful of lines.\n- What is done and merged.\n- What is deliberately not done yet.\n- Anything a fresh session would otherwise get wrong.\n\nNext: <the one thing that happens next>\n",
  "loop-contract.md": "# The bench\n\nSix engineering subagents: `architect`, `implementer`, `ui-engineer`, `security-auditor`, `reviewer` and `docs-writer`; each one's description says when to use it. The **lead**, your main session, orchestrates; each agent does bounded work. This file is the loop's contract, and every agent reads it.\n\n**The loop:** `/brief` writes the brief → `/start-slice` runs `implementer` or `ui-engineer` → `security-auditor` **if triggered** → `reviewer` plants → the lead runs `/close-slice`.\n\n## The loop contract\n\n1. **One brief per slice, as a file.** `/brief` writes `brief.md` in the slice folder, `<main checkout>/.mktrue/slices/<slice-id>/`. The main checkout holds the repository's `.git` directory, so every worktree shares the folder; `.mktrue/` is git-ignored, never committed and never scanned by the prose budgets. The folder is always written out as an absolute path, never as a shell variable. Every agent is told `Read <slice folder>/brief.md and follow it exactly.` plus its role. The first line of every agent prompt names the slice, the role and the slice folder's absolute path, because `mktrue audit` attributes each agent from it (decision 0023). Every agent reads `CLAUDE.md`, `docs/STATE.md`, its brief and the sections the brief cites, nothing wider. Nobody pastes a summary of another agent's work into a prompt — agents read the reports the lead saved.\n\n2. **Reports come back as text; the lead saves them.** An agent writes no report file. It returns its report as its final message, **at most 600 words**, leading with the verdict: then must-fix findings with `file:line` (follow-ups as a count), the calls it judged that need a ruling, the plant table or the lines to plant, and the gate results. The lead saves that message **verbatim** to `<slice folder>/<role>.md` before spawning the next agent, and later agents read the saved file.\n\n3. **Never resume a finished agent.** Resuming replays its whole transcript. A follow-up is a **fresh** agent with a short addendum to the brief and the saved report paths. A slice needing more than about 150 tool calls is two agents.\n\n4. **Two full gate runs per slice, not four.** The implementer runs the full chain once, at the end, package by package and in the foreground. The lead runs it again at `/close-slice`, and **only the lead's numbers are quoted** anywhere. The reviewer runs only the suites its plants target; the auditor runs probes, not suites.\n\n5. **Audit only when triggered.** The `security-auditor` runs when the diff touches any of: __MKTRUE_AUDIT_TRIGGERS__. Otherwise the record says \"audit not triggered\" and why. Auditor and reviewer never run at once.\n\n6. **One canonical record.** At close the lead writes `<slice folder>/record.md`: what landed, rulings, the audit verdict, the plant table, the close-run numbers, and what is owed to the founder. Every other artefact — the pull request body, the board entry, the log — is derived from it, never written separately.\n\n## What the contract must never cut\n\n- **Mutation plants, every slice.** A plant and the run that proves it touch scratch space only. If you need the plant rules, read `.claude/reference/plant.md`.\n- **Per-slice verification.** Never batch audits or reviews across slices. Every commit on the integration branch stays independently green.\n- **Decisions batched at kickoff.** `/start-milestone` publishes one kickoff page, `docs/design/<milestone>-kickoff.md`, with every open call, its options and its cost. Slices do not accumulate questions.\n- **The device pass**, by a person, on a phone.\n\n## Standing rules\n\n1. **Never commit on a subagent's green.** Run `git status`, re-run what you are about to trust, and stage deliberately — never `git add -A`.\n2. **Changes to the authentication surface are never routine.** They need an explicit instruction and a security-auditor pass.\n3. **Known re-run traps.** After a SIGTERM, or a step killed under memory pressure, re-run only the steps that had not passed, with a larger heap. Pass long text to a CLI with `--body-file`, not inline. Stop processes by PID, never `pkill -f`.\n\n## The gates\n\n__MKTRUE_GATES__\n",
  "references/plant.md": "# Plant a bug\n\nA test you have not seen fail is a test you have not seen work.\n\n## Steps\n\n1. Pick the code the slice changed. Plants go where the work was, not across the codebase.\n2. Introduce one deliberate bug. Useful kinds:\n   - invert a condition\n   - change a boundary by one\n   - drop an `await`\n   - remove a permission or ownership check\n   - return the default instead of the computed value\n   - swap two arguments of the same type\n3. Run the suite.\n4. **Caught** means the test did its job. Record it and revert.\n5. **Survived** means a hollow test. Record the file, the assertion that should have failed, and what it would take to catch it. Revert.\n6. Repeat until every meaningful path in the diff has been probed.\n7. Revert every plant. Confirm with `git diff` that the tree is clean and the suite is green.\n\n## Rules\n\n- Never leave a plant in the tree. Check before you finish, every time.\n- Never plant in code the slice did not touch.\n- **A plant and the test run that proves it touch scratch space only**: a fresh directory made for the plant, with `mktemp -d`. Never the real home directory. Never the shared temporary directory itself, or anything in it the plant did not create.\n- **Never plant in shared test support** — a helper every suite imports. One bad helper acts on the whole machine, from every suite at once.\n- **A plant that needs a destructive call replaces the target with the scratch directory first**, then plants. A deletion aimed anywhere else is not a plant.\n- A plant that cannot be written for some path is itself a finding: that path has no observable behaviour to test.\n\n## Done when\n\nEvery plant is reverted, the suite is green, and each surviving plant is recorded as a hollow test with its fix.\n",
  "references/worktree.md": "# Work in a worktree\n\nOne slice, one worktree. The integration branch is never the desk.\n\n## Steps\n\n1. Branch from __MKTRUE_BASE_BRANCH__. A deployed branch is never a base.\n2. Create the worktree under `.claude/worktrees/<slice-id>`, so nothing outside the checkout changes and the agent harness can find it.\n3. Install dependencies there only if the slice touches them.\n4. Work only inside it, by absolute path, for the whole slice.\n5. `/close-slice` removes the worktree and deletes the branch, and only once it has read the pull request's state as `MERGED`. Never before.\n\n## Rules\n\n- Never commit directly to the deployed branch.\n- Two slices never share a worktree. A second slice gets its own.\n- **The worktree has no environment file and no secrets — leave it that way.** Both are git-ignored for a reason. A gate that needs them should be satisfiable with the example file and placeholder values.\n- Never run a destructive or production-facing script from a worktree, or from anywhere. That is a person's job.\n- An abandoned worktree is drift you can see. Remove it.\n\n## Done when\n\nThe slice's work is isolated, and the branch it came from is untouched.\n",
  "rules/01-where-to-look-first.md": "## Where to look first\n\n__MKTRUE_NAME__ — __MKTRUE_PURPOSE__\n\nRead these, in this order, and stop when you know enough:\n\n- __MKTRUE_PATH_STATE__ — where things stand right now. Every session, first.\n- __MKTRUE_PATH_ROADMAP__ — the milestone ladder, and what is out of scope. When planning.\n- __MKTRUE_PATH_DECISIONS_INDEX__ — one line per decision. To find one.\n- __MKTRUE_PATH_DECISIONS__ — a single decision, in full. Only when something cites it.\n- __MKTRUE_PATH_DESIGN__ — the plan for the work you are on. When building.\n- `<main checkout>/.mktrue/slices/<slice-id>/brief.md` — the brief for the slice you are on. While a slice runs.\n- __MKTRUE_PATH_LOG__ — what already happened. Rarely, and never in a hurry.\n\nDo not read the whole docs tree to orient yourself. The state file exists so you do not have to.\n\nThis block is written by mktrue __MKTRUE_KIT_VERSION__ and is replaced by `mktrue sync`. Everything outside its markers belongs to this repository: mktrue never overwrites it.\n",
  "rules/02-stack-and-versions.md": "## 2 · Stack and versions\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nThe languages, runtimes and pinned versions this product uses, and the one command that runs each part.\n\nKeep it to what an agent needs before it writes a line: versions, package manager, how to run and how to test. Anything longer belongs in a decision file.\n",
  "rules/03-architecture-and-boundaries.md": "## 3 · Architecture and boundaries\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nThe shape of the product: what the pieces are, which direction dependencies point, and what is not allowed to cross which line.\n\nName the boundaries that must not be crossed, because those are the ones an agent breaks first.\n",
  "rules/04-how-work-runs.md": "## 4 · How work runs\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nWork runs in slices. Each slice: a brief, a build, a security audit when it is earned, a review that plants bugs, then a close that runs the gates and replaces the state.\n\nThe gates are: __MKTRUE_GATES__\n\nA slice does not close with a red gate. Add what else is true of work here.\n",
  "rules/05-testing-and-plants.md": "## 5 · Testing and plants\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nTests assert behaviour, not implementation. Every slice ends with planted bugs proving the tests catch them; a plant that survives is a hollow test and is recorded as one.\n\nAdd this product's own testing rules: what must have a test before it ships, and what is deliberately not tested.\n",
  "rules/06-security-and-data-classes.md": "## 6 · Security posture and data classes\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nThis product holds: __MKTRUE_DATA_CLASSES__. Sign-in: __MKTRUE_AUTH__.\n\nEvery route is private unless it was deliberately made public. Missing configuration makes the service refuse to boot; it never falls back to something permissive. Data above never reaches a log, an error message, a URL or an analytics call.\n\nA slice touching any of these runs the security auditor: __MKTRUE_AUDIT_TRIGGERS__.\n",
  "rules/07-conventions.md": "## 7 · Conventions\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nCode, identifiers, file names, comments and commit messages are in English. The interface is in: __MKTRUE_LANGUAGES__. A domain in another language does not make the codebase that language.\n\nCommits and pull request titles follow Conventional Commits: `type(scope): subject`, lowercase, no full stop, with `feat`, `fix`, `docs`, `chore`, `refactor`, `test` or `ci` as the type. Add this product's scopes, naming and formatting rules here.\n",
  "rules/08-agent-permissions.md": "## 8 · What agents may and may not do\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nNever: read secret files, force-push, rewrite published history, commit to `main` directly, install a dependency without a decision entry, or send this repository's contents anywhere.\n\nConfiguration enforces the first three as far as a rule can name them. `.claude/settings.json` denies reading `.env` and `.env.*` (`.env.example`, `.env.sample` and `.env.template` stay readable) and the key files `*.pem`, `*.key`, `*.p12`, `id_rsa`, `id_ecdsa` and `id_ed25519`; `source` and `.` of `.env` and of a file ending in `.env`, `.env.local` or `.env.production`; `git push` with `--force`, `-f`, a `+` refspec, `--mirror` or `--delete`; `git reset --hard`, `git filter-branch` and `git filter-repo`. `mktrue check` reports when one of those rules goes missing or a `!` rule reopens one. It does not stop a command spelled another way (`git push -uf`, `git -C . push --force`, `source .env.staging`), a file outside the working directory, or a script that opens a secret itself. The other three are rules an agent follows: nothing enforces them but this file.\n",
  "rules/09-budgets-and-drift.md": "## 9 · Budgets and drift\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\n| Document          | Budget, in characters      |\n| ----------------- | -------------------------- |\n| this rules file   | __MKTRUE_BUDGET_RULES__    |\n| `docs/STATE.md`   | __MKTRUE_BUDGET_STATE__    |\n| one decision file | __MKTRUE_BUDGET_DECISION__ |\n\nThese are enforced by a gate, not by good intentions. Over budget is a finding.\n\n`mktrue check` reports drift: files mktrue owns that were edited without a pin, a kit version behind, budgets exceeded, missing permission rules. It runs in CI on every push.\n",
  "rules/10-where-things-live.md": "## 10 · Where things live\n\n<!-- Owned by this repository. mktrue renders this heading and never touches what follows. -->\n\nThe file map: which directory holds what, and where a new file of each kind belongs.\n\nKeep it to the directories an agent has to choose between. A tree that lists every file rots within a week.\n",
  "settings/claude-code.json": "{\n  \"permissions\": {\n    \"deny\": [\n      \"Read(.env)\",\n      \"Read(.env.*)\",\n      \"Read(!.env.example)\",\n      \"Read(!.env.sample)\",\n      \"Read(!.env.template)\",\n      \"Read(*.pem)\",\n      \"Read(*.key)\",\n      \"Read(*.p12)\",\n      \"Read(id_rsa)\",\n      \"Read(id_ecdsa)\",\n      \"Read(id_ed25519)\",\n      \"Bash(source .env)\",\n      \"Bash(source *.env)\",\n      \"Bash(source *.env.local)\",\n      \"Bash(source *.env.production)\",\n      \"Bash(. .env)\",\n      \"Bash(. *.env)\",\n      \"Bash(. *.env.local)\",\n      \"Bash(. *.env.production)\",\n      \"Bash(git push --force*)\",\n      \"Bash(git push -f*)\",\n      \"Bash(git push * --force*)\",\n      \"Bash(git push * -f*)\",\n      \"Bash(git push * +*)\",\n      \"Bash(git push --mirror*)\",\n      \"Bash(git push * --mirror*)\",\n      \"Bash(git push --delete*)\",\n      \"Bash(git push * --delete*)\",\n      \"Bash(git reset --hard*)\",\n      \"Bash(git filter-branch*)\",\n      \"Bash(git filter-repo*)\"\n    ]\n  }\n}\n",
  "workflows/mktrue.yml": "# Written by mktrue and updated by `mktrue sync`. Your own gates live in ci.yml.\nname: mktrue\n\non:\n  push:\n  pull_request:\n\npermissions:\n  contents: read\n\njobs:\n  check:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4.4.0\n        with:\n          persist-credentials: false\n\n      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0\n        with:\n          node-version: \"24\"\n\n      - name: install mktrue __MKTRUE_KIT_VERSION__\n        run: |\n          mkdir \"$RUNNER_TEMP/mktrue\"\n          cd \"$RUNNER_TEMP/mktrue\"\n          echo '{\"private\": true}' > package.json\n          npm install --ignore-scripts --no-audit --no-fund --save-exact \"mktrue@__MKTRUE_KIT_VERSION__\"\n\n      - name: verify registry signatures\n        run: cd \"$RUNNER_TEMP/mktrue\" && npm audit signatures\n\n      - name: mktrue check\n        run: '\"$RUNNER_TEMP/mktrue/node_modules/.bin/mktrue\" check'\n"
};
